import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class OneBasedArithmeticV5 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine().trim());
        long[] ones = new long[17];
        for (int i = 1; i < 17; ++i) {
            ones[i] = 10 * ones[i - 1] + 1;
        }
        long ans = dfs(ones, n, 16);
        System.out.println(ans);
    }

    private static long dfs(long[] ones, long n, int idx) {
        long quot = n / ones[idx];
        long rem = n % ones[idx];
        long used = quot * idx;
        if (rem == 0) return used;
        else return used + Math.min(dfs(ones, rem, idx - 1),
                idx + dfs(ones, ones[idx] - rem, idx - 1));
    }
}
